test:
def test_urgent_titles_filters():
    tickets = [
        {'id': 1, 'title': 'Server down', 'urgent': True},
        {'id': 2, 'title': 'Typo in docs', 'urgent': False},
        {'id': 3, 'title': 'Data loss', 'urgent': True},
    ]
    assert urgent_titles(tickets) == ['Server down', 'Data loss'], 'must return titles of urgent tickets only, in order'

def test_titles_by_id_maps_all_tickets():
    tickets = [{'id': 1, 'title': 'Server down', 'urgent': True}, {'id': 2, 'title': 'Typo', 'urgent': False}]
    assert titles_by_id(tickets) == {1: 'Server down', 2: 'Typo'}, 'must map every ticket id to its title, urgent or not'

def test_empty_ticket_list():
    assert urgent_titles([]) == [], 'no tickets means no urgent titles'
    assert titles_by_id([]) == {}, 'no tickets means an empty mapping'

canonical:
def urgent_titles(tickets):
    return [t['title'] for t in tickets if t['urgent']]


def titles_by_id(tickets):
    return {t['id']: t['title'] for t in tickets}
